package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.Dizimista; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/dizimistas") public class DizimistaRestController { final DizimistaApplicationService s; public DizimistaRestController(DizimistaApplicationService s){this.s=s;} @PostMapping public ResponseEntity<Dizimista> criar(@Valid @RequestBody DizimistaRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(null,r));} @PutMapping("/{uuid}") public Dizimista atualizar(@PathVariable UUID uuid,@Valid @RequestBody DizimistaRequest r){return s.salvar(uuid,r);} @GetMapping public List<Dizimista> listar(){return s.listar();} }
